    "content": "Akıllı sistemlere giriş ve temel kavramlarYapay Sinir Ağları yapısı ve çalışma prensipleriİleri beslemeli yapay sinir ağlarıGeri beslemeli yapay sinir ağlarıÖğreticili öğrenme algoritmaları (Geri yayılım, Levenberg-Marquardt)Öğreticisiz öğrenme algoritmaları (Kohonen ağları, K-means)Bulanık mantık temelleri ve üyelik fonksiyonlarıBulanık çıkarım sistemleriGenetik algoritmalar ve optimizasyonAkıllı sistemlerle sistem tanılamaAkıllı kontrol sistemleriSinyal işlemede akıllı sistem uygulamalarıGörüntü işlemede akıllı sistem uygulamaları",
