    "resources": "Kaynaklar: Haykin, S., Neural Networks and Learning Machines, 3rd Edition, Pearson, 2009.; Ders Notları: Yapay sinir ağları, bulanık mantık ve genetik algoritmalara ilişkin teorik ders notları ve Python uygulamaları öğrencilerle paylaşılacaktır. Örnek problemler ve vaka çalışmaları ders materyalleri arasında yer almaktadır.",
