      "Bulanık mantık temelleri, üyelik fonksiyonları ve bulanık kümeler",
      "Bulanık çıkarım sistemleri: Mamdani ve Sugeno modelleri",
      "Bulanık mantık ile kontrol sistemleri ve uygulamaları",
      "Genetik algoritmalar: Temel kavramlar, operatörler ve optimizasyon",
      "Sinyal işlemede akıllı sistem uygulamaları, özellik çıkarma ve sınıflandırma",
      "Akıllı sistemler: kapsam ve temel kavramlar",
      "İleri alan kavramları",
      "Matematiksel modelleme"
