    "instructor": "Prof. Dr. S. Batuhan AKBEN https://akbis.osmaniye.edu.tr/@batuhanakben batuhanakben@osmaniye.edu.tr",
    "purpose": "Bu dersin amacı öğrencilerin veri bilimi ve analitik ile ilgili veri analizi, veri dönüştürme, veri yorumlama ve benzeri giriş düzeyindeki konular hakkında bilgi edinmelerini sağlamaktır. Öğrenciler bu bilgiler ile iş hayatında araştırmalarında karşılaşılabilecekleri veri elde etme, veri girişi, veri yorumlama ve veri ile ilgili gerçek problemleri tahmin etme konusunda fikir sahibi olurlar. Veriye dayalı modeller geliştirmek, bu modelleri veri bilimi alanında yaygın olarak tercih edilen yazılımlardan (MATLAB, R, Python ya da benzeri) birini kullanarak uygulamak ve sonuçları etkin şekilde paylaşmak konusunda da bilgi sahibi olurlar.",
    "content": "Veri Bilimi ve Analitiğine Giriş, Veri Analizi, Veri Dönüşümü, Veri Yorumlama, Veri Edinimi, Veri Girişi, Gerçek Veri ile İlişkili Problemlerin Tahmini, Veriye Dayalı Modellerin Geliştirilmesi, Yazılım Kullanımı ve Sonuçların Etkili Paylaşımı",
    "methods": "Teorik Dersler, Pratik Uygulamalar, Veri Analizi, Veri Dönüşümü, Veri Yorumlama, Model Geliştirme, Yazılım Kullanımı, Sonuçların Etkili Paylaşımı",
