    "instructor": "Prof. Dr. Ufuk Bal ufukbal@osmaniye.edu.tr",
    "purpose": "Bu dersin amacı; biyomedikal görüntülerin sayısal işlenmesi, iyileştirilmesi ve bölütlenmesi konularında ileri düzey bilgi sağlamaktır. Özellikle Radon dönüşümü kullanarak 3D görüntü rekonstrüksiyonu, görüntü etiketleme, makine öğrenmesi ve derin öğrenme tabanlı sınıflandırma tekniklerinin biyomedikal görüntüler üzerindeki uygulamalarını teorik ve pratik olarak öğretmektir.",
    "content": "Biyomedikal görüntülerin temel kavramları ve görüntü işleme temelleri; Uzamsal ve frekans domeni filtreleri; Görüntü iyileştirme teknikleri; Görüntü bölütleme algoritmaları; Radon dönüşümü teorisi ve 3D görüntü rekonstrüksiyon yöntemleri; Görüntü işleme etiketleme işlemleri; Biyomedikal görüntü analizi ve öznitelik çıkarma; Makine öğrenmesi ile sınıflandırma; Derin öğrenme temelleri ve biyomedikal uygulamaları.",
    "methods": "Anlatım, Problem Çözme, Tartışma, Bilgisayar Destekli Simülasyon (Matlab/Python).",
    "resources": "Kaynaklar: Biomedical Image Analysis, Rangaraj M. Rangayyan; Ders Notları: Biomedical Image Analysis, Rangaraj M. Rangayyan",
