    "prerequisites": "Yok",
    "instructor": "Atama Bekliyor",
    "purpose": "Doğru gerilim kıyıcıları alanındaki ileri modelleri analiz etme, uygun mühendislik yöntemlerini seçme ve çözüm sonuçlarını doğrulama yetkinliği kazandırmak.",
    "content": "Doğru gerilim kıyıcıları; enerji dönüşümünün temelleri, devre ve sistem modelleri, anahtarlama yapıları, denetim stratejileri, kararlılık ve güç kalitesi, kayıp ve verim analizi, tasarım doğrulama, sürdürülebilir enerji uygulamaları boyutlarıyla ele alınır.",
    "methods": "Kuramsal anlatım, matematiksel modelleme, teknik problem çözümü, benzetim veya deney sonuçlarının tartışılması.",
    "resources": "NIST sensör ve ölçüm bilimi yayınları; NIST TN 1297 ölçüm belirsizliği rehberi; güncel hakemli algılayıcı sistemleri literatürü.",
