    "purpose": "Mühendislikte veri işleme teknikleri alanındaki ileri modelleri analiz etme, uygun mühendislik yöntemlerini seçme ve çözüm sonuçlarını doğrulama yetkinliği kazandırmak.",
    "content": "Mühendislikte veri işleme teknikleri; veri gösterimi ve ön işleme, özellik çıkarımı, model kurma ilkeleri, öğrenme ve kestirim yöntemleri, başarım ölçütleri, doğrulama ve genelleme, hesaplama araçları, etik ve güvenilir yapay zekâ boyutlarıyla ele alınır.",
    "methods": "Kuramsal anlatım, matematiksel modelleme, teknik problem çözümü, benzetim veya deney sonuçlarının tartışılması.",
    "resources": "NIST sensör ve ölçüm bilimi yayınları; NIST TN 1297 ölçüm belirsizliği rehberi; güncel hakemli algılayıcı sistemleri literatürü.",
