      "Derin öğrenme: CNN ve RNN modelleri",
      "Doğal dil işleme ve zaman serisi analizleri",
      "Görüntü işleme uygulamaları",
      "Optimizasyon teknikleri ve hiperparametre ayarlama",
      "Güncel yapay zekâ uygulamaları ve vaka çalışmaları",
      "Yapay zeka uygulamaları: kapsam ve temel kavramlar",
      "Veri gösterimi ve ön işleme"
