    "content": "Doğal dil işleme; veri gösterimi ve ön işleme, özellik çıkarımı, model kurma ilkeleri, öğrenme ve kestirim yöntemleri, başarım ölçütleri, doğrulama ve genelleme, hesaplama araçları, etik ve güvenilir yapay zekâ boyutlarıyla ele alınır.",
