    "purpose": "Bu dersin amacı, yenilenebilir enerji sistemlerinin güvenli, verimli ve kararlı bir şekilde çalışmasını sağlamak için gerekli olan kontrol tekniklerini öğretmektir. Öğrenciler güneş, rüzgar ve enerji depolama sistemlerinin dinamik davranışlarını analiz etmeyi; inverter, dönüştürücü ve mikroşebeke bileşenlerinin kontrolünü gerçekleştirmeyi; ayrıca yapay zekâ ve tahminsel kontrol gibi ileri teknolojileri uygulamayı öğrenirler. Ders, hem teorik hem uygulamalı içerikleriyle, yenilenebilir enerji sistemlerinde kontrol mühendisliğine bütünsel bir bakış sunar.",
    "content": "Yenilenebilir Enerji Sistemlerine GirişGüneş ve Rüzgar Enerjisi Sistemlerinin Dinamik DavranışıTemel Kontrol Teorisi: Geri Besleme, Kararlılık ve RegülasyonPV Sistemlerinde MPPT (Maksimum Güç Noktası Takibi) Kontrol TeknikleriRüzgar Türbinlerinde Pitch ve Tork KontrolüGüç Elektroniği Arayüzleri: İnverter Kontrolü ve DC-DC DönüştürücülerMikroşebekelerde Enerji Yönetimi ve Dağıtık KontrolFrekans ve Gerilim Regülasyonu: Ada ve Şebeke Bağlantılı ModlarEnerji Depolama Sistemlerinin Kontrolü ve EntegrasyonuSCADA, IoT ve Haberleşme Protokolleri ile Uzaktan İzleme ve KontrolYapay Zekâ ve Makine Öğrenmesi ile Tahminsel Kontrol UygulamalarıEntegre Sistem Tasarımı",
    "methods": "Bu ders, teorik ve uygulama temelli bir ders olarak yürütülmekte olup, öğrencilerin kavramsal ve analitik becerilerini geliştirmek için aşağıdaki yöntem ve teknikler kullanılacaktır: Ders Anlatımı Simulasyonlar Ödevler Proje Final Sınavı",
    "resources": "Kaynaklar: Renewable Energy Systems: Modelling, Optimization and Control. Ahmad Taher Azar, Nashwa Ahmad Kamal. Academic Press, 2021.",
    "sdgs": [
      "7",
      "9",
      "13"
    ],
    "outcomes": [
      "Yenilenebilir enerji kaynakları kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Güç elektroniği ve enerji sistemleri alanındaki uygulamaları karşılaştırır.",
      "Yenilenebilir enerji kaynakları için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Yenilenebilir enerji kaynakları faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Yenilenebilir enerji kaynakları bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Yenilenebilir Enerji Sistemlerine Giriş",
      "Güneş ve Rüzgar Enerjisi Sistemlerinin Dinamik Davranışı",
      "Temel Kontrol Teorisi: Geri Besleme, Kararlılık ve Regülasyon",
      "PV Sistemlerinde MPPT (Maksimum Güç Noktası Takibi) Kontrol Teknikleri",
      "Rüzgar Türbinlerinde Pitch ve Tork Kontrolü",
      "Güç Elektroniği Arayüzleri: İnverter Kontrolü ve DC-DC Dönüştürücüler",
      "Mikroşebekelerde Enerji Yönetimi ve Dağıtık Kontrol",
      "Frekans ve Gerilim Regülasyonu: Ada ve Şebeke Bağlantılı Modlar",
      "Enerji Depolama Sistemlerinin Kontrolü ve Entegrasyonu",
      "SCADA, IoT ve Haberleşme Protokolleri ile Uzaktan İzleme ve Kontrol",
      "Yapay Zekâ ve Makine Öğrenmesi ile Tahminsel Kontrol Uygulamaları",
      "Entegre Sistem Tasarımı",
      "Yenilenebilir enerji kaynakları: kapsam ve temel kavramlar",
      "Enerji dönüşümünün temelleri",
      "Devre ve sistem modelleri"
    ],
